const budgetPercent=(spent,budget)=>budget>0?spent/budget*100:0;
function shiftMonth(m,offset){const [y,n]=m.split('-').map(Number);const d=new Date(y,n-1+offset,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}
