let month=localDate().slice(0,7),scope='all',page='dashboard',search='',filters={user:'',category:'',type:'',payment:'',sub:'',from:'',to:'',min:'',max:''};
let comparison='month';
function validState(s){return !!(s&&s.version===1&&typeof s.household==='string'&&Number.isFinite(s.budget)&&s.budget>=0&&Array.isArray(s.users)&&s.users.length&&s.users.every(u=>typeof u.id==='string'&&typeof u.name==='string'&&typeof u.short==='string'&&['admin','member'].includes(u.role)&&Number.isFinite(u.budget)&&u.budget>=0)&&s.users.some(u=>u.role==='admin')&&s.users.some(u=>u.id===s.currentUser)&&Array.isArray(s.categories)&&s.categories.length&&s.categories.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&typeof c.icon==='string'&&Number.isFinite(c.budget)&&c.budget>=0&&Array.isArray(c.subs)&&c.subs.length&&c.subs.every(v=>typeof v==='string'))&&Array.isArray(s.expenses)&&s.expenses.every(e=>typeof e.id==='string'&&Number.isFinite(e.amount)&&e.amount>0&&/^\d{4}-\d{2}-\d{2}$/.test(e.date)&&!isNaN(Date.parse(e.date))&&s.users.some(u=>u.id===e.user)&&s.categories.some(c=>c.id===e.category)&&['need','want'].includes(e.type)&&['merchant','note','sub','payment'].every(k=>typeof e[k]==='string')&&(!e.receipt||/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(e.receipt)))&&s.favorites&&typeof s.favorites==='object'&&Object.values(s.favorites).every(v=>Array.isArray(v)&&v.every(x=>typeof x==='string'))&&validIncomeState(s));}
function save(){if(CLOUD_ENABLED)return false;try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('تعذر الحفظ. مساحة المتصفح غير كافية؛ صدّر نسخة احتياطية.');return false;}}
function commit(change){if(CLOUD_ENABLED){toast('تعذر الحفظ: استخدم الاتصال بقاعدة البيانات.');return false;}const old=JSON.stringify(state);change();if(!save()){state=JSON.parse(old);return false;}return true;}
const userBy=id=>state.users.find(u=>u.id===id)||state.users[0];
const catBy=id=>state.categories.find(c=>c.id===id)||state.categories.at(-1);
const current=()=>userBy(state.currentUser);
const isAdmin=()=>current().role==='admin';
const monthName=m=>new Intl.DateTimeFormat('ar-JO',{month:'long',year:'numeric'}).format(new Date(`${m}-01T12:00:00`));
const displayDate=d=>new Intl.DateTimeFormat('ar-JO',{day:'numeric',month:'short',numberingSystem:'latn'}).format(new Date(`${d}T12:00:00`));
function entries(m=month,user=scope){return state.expenses.filter(e=>e.date.startsWith(m)&&((!isAdmin()||user==='mine')?e.user===state.currentUser:user==='all'||e.user===user));}
function filtered(){return entries().filter(e=>(!filters.user||e.user===filters.user)&&(!filters.category||e.category===filters.category)&&(!filters.type||e.type===filters.type)&&(!filters.payment||e.payment===filters.payment)&&(!filters.sub||e.sub.toLowerCase().includes(filters.sub.toLowerCase()))&&(!filters.from||e.date>=filters.from)&&(!filters.to||e.date<=filters.to)&&(!filters.min||e.amount>=Number(filters.min))&&(!filters.max||e.amount<=Number(filters.max))&&(!search||[e.merchant,e.note,e.sub,e.amount,e.date,e.payment,catBy(e.category).name,userBy(e.user).name].join(' ').toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));}
const avatar=u=>`<span class="avatar" style="background:${safeColor(u.color)};color:${safeColor(u.ink)}">${escapeHTML(u.short[0])}</span>`;
function safeColor(c){return /^#[0-9a-f]{3,8}$/i.test(c)?c:'#819578';}
function catIcon(c){return `<span class="category-icon" style="color:${safeColor(c.color)};background:${safeColor(c.color)}18">${icon(c.icon)}</span>`;}
function hydrate(){ $$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon)); }
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function showModal(title,html){$('#modalTitle').textContent=title;$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();hydrate();}
function closeModal(){$('#modal').close();}
const titles={dashboard:'نظرة عامة',expenses:'المصاريف',income:'الدخل الإضافي',budgets:'الميزانيات',members:'أفراد العائلة',reports:'التقارير والتحليلات',categories:'التصنيفات',settings:'الإعدادات'};
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
const monthControl=()=>`<input type="month" class="month-input" id="monthControl" aria-label="شهر التقرير" value="${month}">`;
const addButton=()=>`<button class="button primary" data-action="add-expense">${icon('plus')}إضافة مصروف</button>`;
function render(){
 if(!state)return;
 if(state.cloud)applyCloudBudgets();
 page=location.hash.slice(1)||'dashboard';if(!titles[page])page='dashboard';
 $('#breadcrumb').textContent=titles[page];$('#householdLabel').textContent=state.household;$('#profileName').textContent=current().name;
 $('.profile>.avatar').outerHTML=avatar(current());$('.topbar-actions>.avatar').outerHTML=avatar(current());
 $('#expenseCount').textContent=entries(month,'all').length;$('#notificationDot').hidden=alerts().length===0;
 $$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));
 const views={dashboard:dashboard,expenses:expensesPage,income:incomePage,budgets:budgetsPage,members:membersPage,reports:reportsPage,categories:categoriesPage,settings:state.cloud?cloudSettingsPage:settingsPage};
 $('#main').innerHTML=views[page]();hydrate();
 $('#monthControl')?.addEventListener('change',e=>{if(e.target.value){month=e.target.value;render();}});
 $('#quickForm')?.addEventListener('submit',quickAdd);
 $('#searchInput')?.addEventListener('input',e=>{search=e.target.value;refreshTransactions();});
 $$('[data-filter]').forEach(el=>el.addEventListener('input',()=>{filters[el.dataset.filter]=el.value;refreshTransactions();}));
 $('#categorySearch')?.addEventListener('input',e=>renderCategoryCards(e.target.value));
 $('#comparisonControl')?.addEventListener('change',e=>{comparison=e.target.value;render();});
 $('#settingsForm')?.addEventListener('submit',saveSettings);
 $('#restoreInput')?.addEventListener('change',restoreBackup);
 if(state.cloud)cloudDecorate();
}
function stats(){
 const list=entries(),spent=sum(list),householdScope=scope==='all'&&isAdmin();
 const budget=householdScope?householdBudget():userBy(scope==='mine'||!isAdmin()?state.currentUser:scope).budget;
 const income=sum(incomeEntries()),available=Math.round((budget+income)*1000)/1000;
 const prev=sum(entries(shiftMonth(month,-1))),diff=prev?(spent-prev)/prev*100:null,remaining=Math.round((available-spent)*1000)/1000,pct=budgetPercent(spent,available);
 return `<div class="stats-grid with-income">
 <article class="stat-card featured"><div class="stat-top"><span>المصاريف هذا الشهر</span><span class="stat-icon">${icon('wallet')}</span></div><div class="stat-value">${money(spent)} <small>JOD</small></div><div class="stat-foot"><span class="pill ${diff>0?'orange':''}">${icon(diff>0?'up':'down')}${diff===null?'—':`${Math.abs(diff).toFixed(1)}%`}</span> ${diff===null?'لا توجد بيانات للشهر السابق':'مقارنة بالشهر السابق'}</div></article>
 <article class="stat-card"><div class="stat-top"><span>الميزانية الأساسية</span>${householdScope?`<button class="icon-button no-print" data-action="edit-monthly-budget" aria-label="تعديل الميزانية الشهرية">${icon('edit')}</button>`:`<span class="stat-icon">${icon('target')}</span>`}</div><div class="stat-value" id="baseBudgetValue">${money(budget)} <small>JOD</small></div><div class="stat-foot">${monthName(month)} ${householdScope&&Object.hasOwn(state.monthlyBudgets||{},month)?'· ميزانية خاصة':''}</div></article>
 <article class="stat-card income-stat"><div class="stat-top"><span>الدخل الإضافي</span><button class="icon-button no-print" data-action="add-income" aria-label="إضافة دخل">${icon('plus')}</button></div><div class="stat-value" id="incomeTotalValue">${money(income)} <small>JOD</small></div><div class="stat-foot"><a href="#income">${incomeEntries().length} عملية دخل · عرض السجل</a></div></article>
 <article class="stat-card"><div class="stat-top"><span>${remaining>=0?'الرصيد المتاح':'تجاوز المتاح'}</span><span class="stat-icon">${icon('pie')}</span></div><div class="stat-value ${remaining<0?'warning-text':''}" id="availableBalanceValue">${money(Math.abs(remaining))} <small>JOD</small></div><div class="stat-foot">الميزانية + الدخل − المصاريف</div></article>
 <article class="stat-card"><div class="stat-top"><span>استهلاك المتاح</span><span class="stat-icon">${icon('chart')}</span></div><div class="stat-value">${available>0?pct.toFixed(1):'—'}<small>${available>0?'%':''}</small></div><div class="progress"><span style="width:${Math.min(pct,100)}%;${spent>available?'background:var(--red)':''}"></span></div><div class="stat-foot">${money(spent)} من ${money(available)} دينار</div></article></div>`;
}
function trendPanel(){
 const other=comparison==='year'?`${Number(month.slice(0,4))-1}${month.slice(4)}`:shiftMonth(month,-1),data=entries(),previous=entries(other);
 const calendarDays=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();
 const days=month===localDate().slice(0,7)?Math.max(Number(localDate().slice(8)),...data.map(e=>Number(e.date.slice(8)))):calendarDays;
 const points=Math.min(7,days),buckets=Array(points).fill(0),old=Array(points).fill(0);
 data.forEach(e=>buckets[Math.min(points-1,Math.floor((Number(e.date.slice(8))-1)*points/days))]+=e.amount);
 previous.filter(e=>Number(e.date.slice(8))<=days).forEach(e=>old[Math.min(points-1,Math.floor((Number(e.date.slice(8))-1)*points/days))]+=e.amount);
 const max=Math.max(100,Math.ceil(Math.max(...buckets,...old)/200)*200),x=i=>48+i*468/Math.max(1,points-1),y=v=>170-v/max*143;
 function path(vals){return vals.map((v,i)=>`${i?'L':'M'}${x(i)} ${y(v)}`).join(' ');}
 const previousPeriod=previous.filter(e=>Number(e.date.slice(8))<=days);
 const lines=Array.from({length:5},(_,i)=>{const n=max*i/4;return `<line class="chart-grid" x1="43" y1="${y(n)}" x2="524" y2="${y(n)}"/><text class="chart-label" x="31" y="${y(n)+3}" text-anchor="end">${Math.round(n)}</text>`;}).join('');
 const labels=buckets.map((_,i)=>`<text class="chart-label" x="${x(i)}" y="196" text-anchor="middle">${String(Math.min(days,Math.round(i*(days-1)/Math.max(1,points-1))+1)).padStart(2,'0')}</text>`).join('');
 return `<section class="panel"><div class="panel-head"><div><h2>كيف كان إنفاقنا؟</h2><p>توزيع المصاريف حتى يوم ${days} · دينار أردني</p></div><select id="comparisonControl" aria-label="فترة المقارنة"><option value="month" ${comparison==='month'?'selected':''}>مقارنة بالشهر السابق</option><option value="year" ${comparison==='year'?'selected':''}>مقارنة بالسنة السابقة</option></select></div><div class="chart-legend"><span><i class="legend-dot"></i>${monthName(month)}</span><span><i class="legend-dot previous"></i>${monthName(other)}</span></div><div class="trend-chart"><svg viewBox="0 0 550 205" role="img" aria-label="مقارنة المصاريف حتى يوم ${days}؛ الحالي ${money(sum(data))} والسابق ${money(sum(previousPeriod))} دينار"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#87b99d" stop-opacity=".23"/><stop offset="100%" stop-color="#87b99d" stop-opacity=".01"/></linearGradient></defs>${lines}<path d="${path(buckets)} L516 170 L48 170Z" fill="url(#chartFill)"/><path d="${path(old)}" fill="none" stroke="#c3cebd" stroke-width="2" stroke-dasharray="5 5" stroke-linejoin="round"/><path d="${path(buckets)}" fill="none" stroke="#39795d" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${buckets.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="#fff" stroke="#39795d" stroke-width="1.5"><title>${money(v)} JOD</title></circle>`).join('')}${labels}</svg></div><div class="chart-note">${icon('info')}${previous.length?`فرق الإنفاق لنفس أيام الشهر: ${money(sum(data)-sum(previousPeriod))} دينار`:'لا توجد مصاريف مسجلة في فترة المقارنة.'}</div></section>`;
}
function categoryTotals(list=entries()){return state.categories.map(c=>({...c,total:sum(list.filter(e=>e.category===c.id))})).filter(c=>c.total>0).sort((a,b)=>b.total-a.total);}
function categoryPanel(){const cats=categoryTotals(),total=sum(entries()),top=cats.slice(0,4),rest=cats.slice(4).reduce((s,c)=>s+c.total,0);if(rest)top.push({name:'أخرى',total:rest,color:'#d9dece'});let angle=0;const gradient=top.map(c=>{const start=angle;angle+=c.total/(total||1)*100;return `${safeColor(c.color)} ${start}% ${angle}%`;}).join(',')||'#edf2eb 0% 100%';
 return `<section class="panel"><div class="panel-head"><div><h2>على ماذا نصرف؟</h2><p>المصاريف حسب التصنيف</p></div><a href="#categories" class="text-button">${icon('arrow')}</a></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(${gradient})" role="img" aria-label="توزيع المصاريف حسب التصنيف"><div class="donut-center"><small>إجمالي المصروف</small><strong>${total.toLocaleString('en-US',{maximumFractionDigits:0})}</strong><small>دينار أردني</small></div></div><div class="donut-legend">${top.map(c=>`<div class="donut-item"><span><i class="legend-dot" style="background:${safeColor(c.color)}"></i>${escapeHTML(c.name)}</span><strong>${(c.total/(total||1)*100).toFixed(0)}<small>%</small></strong></div>`).join('')||'<span class="eyebrow">لا توجد مصاريف لهذا الشهر</span>'}</div></div><div class="category-foot"><span>أعلى تصنيف إنفاقًا</span><strong>${cats[0]?`${escapeHTML(cats[0].name)} · ${money(cats[0].total)} JOD`:'—'}</strong></div></section>`;
}
function membersPanel(){const users=isAdmin()?state.users:[current()];return `<section class="panel"><div class="panel-head"><h2>مصاريف الأفراد</h2><a class="text-button" href="#members">أفراد العائلة ${icon('arrow')}</a></div><div class="members-row" style="${users.length!==3?'grid-template-columns:repeat('+Math.min(users.length,3)+',1fr)':''}">${users.map(u=>{const spent=sum(entries(month,u.id)),pct=budgetPercent(spent,u.budget);return `<div class="member-mini"><div class="member-mini-top">${avatar(u)}<div><strong>${escapeHTML(u.short)}</strong><small>${u.role==='admin'?'مدير العائلة':'فرد العائلة'}</small></div></div><div class="member-numbers"><strong>${money(spent)} <small>JOD</small></strong></div><div class="progress"><span style="width:${Math.min(pct,100)}%;background:${spent>u.budget?'#c66b55':safeColor(u.ink)}"></span></div><p class="small-note">${u.budget>0?pct.toFixed(0)+'% من ميزانية '+money(u.budget):'ميزانية 0 دينار'}</p></div>`;}).join('')}</div></section>`;}
function balancePanel(){const list=entries(),total=sum(list),need=sum(list.filter(e=>e.type==='need')),want=total-need,np=total?need/total*100:0,wp=total?100-np:0;return `<section class="panel"><div class="panel-head"><h2>ضروريات أم كماليات؟</h2>${icon('pie')}</div><div class="balance-content"><div class="balance-bar" role="img" aria-label="ضروريات ${np.toFixed(1)}% وكماليات ${wp.toFixed(1)}%"><span style="width:${np}%"></span><span style="width:${wp}%"></span></div><div class="balance-labels"><div><strong><i class="legend-dot" style="background:#51846b"></i>ضروريات <span dir="ltr">${np.toFixed(1)}%</span></strong><small>${money(need)} JOD</small></div><div><strong><i class="legend-dot" style="background:#d1ba89"></i>كماليات <span dir="ltr">${wp.toFixed(1)}%</span></strong><small>${money(want)} JOD</small></div></div><p class="balance-note">${icon('leaf')} ${wp>30?'راجع الكماليات لاكتشاف فرص التوفير.':'التوازن اليوم، راحة لبكرا.'}</p></div></section>`;}
function quickPanel(){return `<form id="quickForm" class="quick-add"><span class="quick-symbol">${icon('spark')}</span><div class="quick-copy"><strong>مصروف جديد؟ سجّله بلحظة</strong><small>اكتب المبلغ والتفاصيل، والباقي علينا</small></div><div class="quick-input-wrap"><input id="quickInput" required aria-label="إضافة سريعة" placeholder="مثلًا: 12 دينار أوبر، أو 35 سوبرماركت..."><button type="submit">إضافة سريعة ${icon('arrow')}</button></div></form>`;}
function table(list,limit=Infinity,actions=true){return list.length?`<div class="table-wrap"><table><thead><tr><th>المصروف</th><th>الفرد</th><th>التصنيف</th><th>التاريخ</th><th>النوع</th><th>المبلغ</th>${actions?'<th class="no-print"> </th>':''}</tr></thead><tbody>${list.slice(0,limit).map(e=>{const c=catBy(e.category),u=userBy(e.user);return `<tr><td><div class="transaction-title">${catIcon(c)}<div><strong>${escapeHTML(e.merchant||e.sub)}</strong><small>${escapeHTML(e.note||e.sub)}${e.receipt?' · فاتورة مرفقة':''}</small></div></div></td><td><div class="member-cell">${avatar(u)}${escapeHTML(u.short)}</div></td><td>${escapeHTML(c.name)}<br><small>${escapeHTML(e.sub)}</small></td><td>${displayDate(e.date)}</td><td><span class="pill ${e.type==='want'?'orange':''}">${e.type==='need'?'ضروري':'كمالي'}</span></td><td class="amount">${money(e.amount)} <small>JOD</small></td>${actions?`<td class="no-print"><div class="transaction-actions"><button class="icon-button" data-action="edit-expense" data-id="${escapeHTML(e.id)}" aria-label="تعديل ${escapeHTML(e.merchant)}">${icon('edit')}</button>${e.receipt?`<button class="icon-button" data-action="receipt" data-id="${escapeHTML(e.id)}" aria-label="عرض الفاتورة">${icon('receipt')}</button>`:''}</div></td>`:''}</tr>`;}).join('')}</tbody></table></div>`:`<div class="empty-state">${icon('wallet')}<h3>مساحة لبداية جديدة</h3><p>لا توجد مصاريف تطابق الفترة أو الفلاتر المحددة.</p><button class="button" data-action="add-expense">${icon('plus')} أضف أول مصروف</button></div>`;}
function alerts(){const result=[],list=entries(month,'all');state.categories.forEach(c=>{const spent=sum(list.filter(e=>e.category===c.id)),p=c.budget>0?spent/c.budget:0;if(spent>c.budget||p>=.8)result.push({title:spent>c.budget?`تجاوزت ميزانية ${c.name}`:`اقتربت من ميزانية ${c.name}`,text:spent>c.budget?`زيادة بمقدار ${money(spent-c.budget)} دينار. راجع المصاريف وخطّط لبقية الشهر.`:`استهلكت ${(p*100).toFixed(0)}% من الميزانية المحددة بـ ${money(c.budget)} دينار.`});});(isAdmin()?state.users:[current()]).forEach(u=>{const spent=sum(list.filter(e=>e.user===u.id));if(spent>u.budget||(u.budget>0&&spent/u.budget>=.8))result.push({title:`ميزانية ${u.short}`,text:`${spent>u.budget?'تجاوز الميزانية بمقدار':'المتبقي لهذا الشهر'} ${money(Math.abs(u.budget-spent))} دينار.`});});return result;}
function dashboard(){const list=entries().sort((a,b)=>b.date.localeCompare(a.date)),alert=alerts()[0];return `${heading('نظرة عامة','كل مصاريف العائلة في مكان واحد. قرارات أوضح، وراحة بال أكثر.',`${monthControl()}${budgetEditButton()}${incomeAddButton()}${addButton()}`)}<div class="dashboard-filter"><div class="tabs"><button data-action="scope" data-scope="all" class="${scope==='all'?'active':''}">${icon('users')} ${isAdmin()?'البيت كاملًا':'نظرة عامة'}</button><button data-action="scope" data-scope="mine" class="${scope==='mine'?'active':''}">مصاريفي</button></div><span class="period-note">${icon('calendar')}${monthName(month)}</span></div>${stats()}<div class="content-grid">${trendPanel()}${categoryPanel()}</div><div class="lower-grid">${membersPanel()}${balancePanel()}</div>${incomePanel(3)}${quickPanel()}<section class="panel"><div class="panel-head"><div><h2>آخر مصاريف العائلة</h2><p>التفاصيل الصغيرة تصنع الصورة الكبيرة</p></div><a class="text-button" href="#expenses">عرض كل المصاريف ${icon('arrow')}</a></div>${table(list,5)}<div class="table-foot"><span>عرض ${Math.min(list.length,5)} من ${list.length} مصروف</span><span>${icon('check')} كل التفاصيل محفوظة</span></div></section><div class="insight-banner">${icon('spark')}<div><strong>${alert?escapeHTML(alert.title):'قرار صغير اليوم، توفير أكبر بكرا'}</strong> · ${alert?escapeHTML(alert.text):'راجع المصاريف مع عائلتك وحددوا هدف التوفير القادم.'}</div><button data-action="go-budgets">مراجعة الميزانيات ←</button></div>`;}
function option(value,label,selected){return `<option value="${escapeHTML(value)}" ${selected===value?'selected':''}>${escapeHTML(label)}</option>`;}
function expensesPage(){return `${heading('المصاريف','سجّل، ابحث، وراجع تفاصيل مصاريف العائلة.',`${monthControl()}<button class="button" data-action="csv">${icon('download')}تصدير</button>${addButton()}`)}${quickPanel()}<section class="panel"><div class="filters"><input class="filter-input search-field" id="searchInput" placeholder="ابحث عن متجر، ملاحظة، مبلغ..." aria-label="البحث في المصاريف" value="${escapeHTML(search)}"><select class="filter-input" data-filter="user" aria-label="الفرد">${option('','كل الأفراد',filters.user)}${(isAdmin()?state.users:[current()]).map(u=>option(u.id,u.short,filters.user)).join('')}</select><select class="filter-input" data-filter="category" aria-label="التصنيف">${option('','كل التصنيفات',filters.category)}${state.categories.map(c=>option(c.id,c.name,filters.category)).join('')}</select><select class="filter-input" data-filter="type" aria-label="نوع المصروف">${option('','كل الأنواع',filters.type)}${option('need','ضروري',filters.type)}${option('want','كمالي',filters.type)}</select><button class="text-button" data-action="clear-filters">مسح الفلاتر</button><details ${Object.entries(filters).some(([k,v])=>['payment','sub','from','to','min','max'].includes(k)&&v)?'open':''}><summary>خيارات بحث إضافية</summary><div class="advanced-filters"><label>من تاريخ<input type="date" class="filter-input" data-filter="from" value="${escapeHTML(filters.from)}"></label><label>إلى تاريخ<input type="date" class="filter-input" data-filter="to" value="${escapeHTML(filters.to)}"></label><label>أقل مبلغ<input type="number" min="0" class="filter-input" data-filter="min" value="${escapeHTML(filters.min)}"></label><label>أعلى مبلغ<input type="number" min="0" class="filter-input" data-filter="max" value="${escapeHTML(filters.max)}"></label><label>التصنيف الفرعي<input class="filter-input" data-filter="sub" value="${escapeHTML(filters.sub)}"></label><label>طريقة الدفع<select class="filter-input" data-filter="payment">${option('','الكل',filters.payment)}${['Visa','نقدي','تحويل بنكي','محفظة إلكترونية'].map(p=>option(p,p,filters.payment)).join('')}</select></label></div></details></div><div id="transactions">${table(filtered())}</div><div class="table-foot" id="transactionSummary">${tableSummary()}</div></section>`;}
function tableSummary(){const list=filtered();return `<span>${list.length} مصروف</span><span>الإجمالي: ${money(sum(list))} JOD</span>`;}
function refreshTransactions(){$('#transactions').innerHTML=table(filtered());$('#transactionSummary').innerHTML=tableSummary();}
function budgetRow(name,budget,spent,kind,id,color= '#628566'){const p=budgetPercent(spent,budget);return `<div class="budget-item"><div class="budget-line"><strong>${escapeHTML(name)}</strong><span>${money(spent)} / ${money(budget)} JOD ${isAdmin()?`<button class="icon-button" data-action="edit-budget" data-kind="${kind}" data-id="${escapeHTML(id)}" aria-label="تعديل ميزانية ${escapeHTML(name)}">${icon('edit')}</button>`:''}</span></div><div class="progress"><span style="width:${Math.min(p,100)}%;background:${spent>budget?'#c66b55':safeColor(color)}"></span></div><div class="budget-detail"><span class="${spent>budget?'warning-text':''}">${spent>budget?'تجاوز بمقدار':'متبقي'} ${money(Math.abs(budget-spent))} دينار</span><span>${budget>0?p.toFixed(1)+'% مستخدم':'ميزانية 0 دينار'}</span></div></div>`;}
function budgetsPage(){return `${heading('الميزانيات','ميزانية واضحة للبيت، ولكل فرد، ولكل تفصيل.',`${monthControl()}${budgetEditButton()}${incomeAddButton()}`)}${stats()}<div class="budget-allocation"><span>الموزع على التصنيفات: <strong>${money(state.categories.reduce((total,c)=>total+c.budget,0))} دينار</strong></span><span>${state.categories.reduce((total,c)=>total+c.budget,0)>availableHouseholdBudget()?'زيادة التوزيع عن المتاح':'غير موزّع'}: <strong>${money(Math.abs(availableHouseholdBudget()-state.categories.reduce((total,c)=>total+c.budget,0)))} دينار</strong></span></div><div class="content-grid"><section class="panel"><div class="panel-head"><h2>ميزانيات التصنيفات</h2><span class="eyebrow">${monthName(month)}</span></div><div class="budget-list">${state.categories.map(c=>budgetRow(c.name,c.budget,sum(entries().filter(e=>e.category===c.id)),'category',c.id,c.color)).join('')}</div></section><div><section class="panel"><div class="panel-head"><h2>ميزانية البيت</h2></div><div class="budget-list">${budgetRow(state.household,isAdmin()?householdBudget():current().budget,sum(entries(month,'all')),'household','household')}</div></section><section class="panel report-section"><div class="panel-head"><h2>ميزانيات الأفراد</h2></div><div class="budget-list">${(isAdmin()?state.users:[current()]).map(u=>budgetRow(u.short,u.budget,sum(entries(month,u.id)),'user',u.id,u.ink)).join('')}</div></section><div class="insight-banner">${icon('info')}ميزانية البيت قابلة للتعديل لكل شهر. الدخل الإضافي يزيد المتاح لذلك الشهر، ومخصصات الأفراد والتصنيفات تبقى مستقلة.</div></div></div>`;}
function membersPage(){return `${heading('أفراد العائلة','تعرّف على إنفاق كل فرد، وخلّوا الصورة أوضح.',`${monthControl()}${isAdmin()?`<button class="button primary" data-action="add-member">${icon('plus')}إضافة فرد</button>`:''}`)}<div class="page-card-grid">${(isAdmin()?state.users:[current()]).map(u=>{const spent=sum(entries(month,u.id)),old=sum(entries(shiftMonth(month,-1),u.id));return `<article class="panel member-card">${avatar(u)}<h2>${escapeHTML(u.name)}</h2><span class="role">${u.role==='admin'?'مدير العائلة':'فرد العائلة'}</span>${u.email?`<p class="member-email" dir="ltr">${escapeHTML(u.email)}</p>`:''}<div class="stat-value">${money(spent)} <small>JOD</small></div><p class="eyebrow">${old?`${((spent-old)/old*100).toFixed(1)}% مقارنة بالشهر السابق`:'لا توجد بيانات للشهر السابق'}</p><div class="progress"><span style="width:${Math.min(budgetPercent(spent,u.budget),100)}%;background:${spent>u.budget?'#c66b55':safeColor(u.ink)}"></span></div><p class="eyebrow">${spent>u.budget?'تجاوز الميزانية':'المتبقي'}: ${money(Math.abs(u.budget-spent))} من ${money(u.budget)} دينار</p><button class="button" data-action="member-details" data-id="${escapeHTML(u.id)}">تفاصيل المصاريف ${icon('arrow')}</button>${isAdmin()?`<button class="text-button" data-action="edit-member" data-id="${escapeHTML(u.id)}" style="margin-top:14px">${icon('edit')}تعديل بيانات الفرد</button>`:''}</article>`;}).join('')}</div>`;}
function reportsPage(){const list=entries(),prev=entries(shiftMonth(month,-1)),lastYear=entries(`${Number(month.slice(0,4))-1}${month.slice(4)}`);return `${heading('التقارير والتحليلات','تقرير شامل يساعد عائلتك على اتخاذ قرارات أفضل.',`${monthControl()}<button class="button" data-action="share-report">${icon('arrow')}مشاركة</button><button class="button primary" data-action="print">${icon('download')}طباعة / حفظ PDF</button>`)}<div class="report-intro"><span class="eyebrow">تقرير مصاريف العائلة · ${monthName(month)}</span><h2>${escapeHTML(state.household)}</h2><p>بلغ إجمالي المصاريف ${money(sum(list))} دينار، موزعة على ${list.length} عملية. ${sum(prev)?`فرق الإنفاق عن الشهر السابق ${money(sum(list)-sum(prev))} دينار (${((sum(list)-sum(prev))/sum(prev)*100).toFixed(1)}%).`:'لا تتوفر بيانات للمقارنة مع الشهر السابق.'}</p></div>${stats()}${incomePanel(Infinity,false)}<div class="content-grid">${trendPanel()}${categoryPanel()}</div><div class="lower-grid">${membersPanel()}${balancePanel()}</div><section class="panel"><div class="panel-head"><h2>المقارنة الشهرية والسنوية</h2></div><div class="report-comparison"><div><small>${monthName(month)}</small><strong>${money(sum(list))} <small>JOD</small></strong></div><div><small>${monthName(shiftMonth(month,-1))}</small><strong>${prev.length?money(sum(prev)):'لا توجد بيانات'}</strong></div><div><small>الشهر نفسه من العام السابق</small><strong>${lastYear.length?money(sum(lastYear)):'لا توجد بيانات'}</strong></div></div></section><div class="content-grid report-section"><section class="panel"><div class="panel-head"><h2>أعلى 5 تصنيفات · أداء الميزانية</h2></div><div class="budget-list">${categoryTotals().slice(0,5).map(c=>budgetRow(c.name,c.budget,c.total,'category',c.id,c.color)).join('')||'<p class="eyebrow">لا توجد مصاريف</p>'}</div></section><section class="panel"><div class="panel-head"><h2>أين تغيّر الإنفاق؟</h2></div><div class="budget-list">${state.categories.map(c=>({name:c.name,change:sum(list.filter(e=>e.category===c.id))-sum(prev.filter(e=>e.category===c.id))})).filter(c=>c.change!==0).sort((a,b)=>Math.abs(b.change)-Math.abs(a.change)).slice(0,6).map(c=>`<div class="budget-item"><div class="budget-line"><strong>${escapeHTML(c.name)}</strong><span dir="ltr">${c.change>0?'+':''}${money(c.change)} JOD</span></div></div>`).join('')||'<p class="eyebrow">لا يوجد تغير مسجل</p>'}</div></section></div><section class="panel report-section"><div class="panel-head"><h2>أكبر 5 مصاريف</h2></div>${table([...list].sort((a,b)=>b.amount-a.amount),5,false)}</section><section class="panel report-section"><div class="panel-head"><h2>تفاصيل جميع العمليات</h2><button class="text-button no-print" data-action="csv">تصدير CSV ${icon('download')}</button></div>${table([...list].sort((a,b)=>b.date.localeCompare(a.date)),Infinity,false)}</section>`;}
function categoryCards(query=''){return state.categories.filter(c=>[c.name,...c.subs].join(' ').includes(query)).map(c=>`<article class="panel category-card"><div class="category-card-heading">${catIcon(c)}${isAdmin()?`<button class="icon-button" data-action="edit-category" data-id="${escapeHTML(c.id)}" aria-label="تعديل ${escapeHTML(c.name)}">${icon('edit')}</button>`:''}</div><h2>${escapeHTML(c.name)}</h2><div class="category-tags">${c.subs.map(s=>`<span>${escapeHTML(s)}</span>`).join('')}</div><p>الميزانية الشهرية: ${money(c.budget)} JOD</p><button class="text-button" data-action="category-expense" data-id="${escapeHTML(c.id)}">${icon('plus')} إضافة مصروف</button></article>`).join('')||'<div class="empty-state">لم نجد تصنيفًا بهذا الاسم.</div>';}
function categoriesPage(){return `${heading('التصنيفات','تصنيفات مرتبة تساعدك تعرف أين تذهب ميزانيتك.',isAdmin()?`<button class="button primary" data-action="add-category">${icon('plus')}إضافة تصنيف</button>`:'')}<input class="filter-input" id="categorySearch" placeholder="ابحث عن تصنيف أو تصنيف فرعي، مثل بنزين أو قهوة..." aria-label="البحث في التصنيفات" style="margin-bottom:22px;max-width:480px"><div class="page-card-grid" id="categoryCards">${categoryCards()}</div>`;}
function renderCategoryCards(q){$('#categoryCards').innerHTML=categoryCards(q);}
function settingsPage(){return `${heading('بيتك، على طريقتك','إعدادات مساحة العائلة وحفظ بياناتك.')}<section class="panel settings-panel"><h2>تفاصيل البيت</h2><form id="settingsForm"><label class="field">اسم العائلة<input name="household" required maxlength="60" value="${escapeHTML(state.household)}" ${!isAdmin()?'disabled':''}></label><label class="field">العملة<input value="الدينار الأردني — JOD" disabled></label>${isAdmin()?'<button class="button primary" type="submit">حفظ التغييرات</button>':''}</form></section><section class="panel settings-panel"><h2>نسخة احتياطية، وراحة بال</h2><p>نزّل نسخة JSON تشمل الدخل والمصاريف والفواتير والميزانيات الشهرية والأفراد، واحتفظ بها في مكان خاص. استعادة النسخة تستبدل بيانات هذا المتصفح بعد تأكيدك.</p><div class="settings-actions"><button class="button" data-action="backup">${icon('download')}تنزيل نسخة احتياطية</button>${isAdmin()?`<label class="button file-label">${icon('layers')}استعادة نسخة<input type="file" accept="application/json,.json" id="restoreInput" hidden></label>`:''}</div></section><section class="panel settings-panel"><h2>حول هذه المساحة</h2><p>هذه نسخة تعمل محليًا باستخدام HTML وCSS وJavaScript. البيانات وصور الفواتير تُحفظ في هذا المتصفح على هذا الجهاز. تبديل الأفراد يتيح تجربة واجهات المدير والعضو، ولا يمثل تسجيل دخول أو حماية أمنية. المصاريف تبدأ من صفر، والمبالغ المحددة مخصصات شهرية.</p><p>الاستخدام المشترك الآمن يحتاج خادمًا مع تسجيل دخول، وصلاحيات فعلية، واتصال HTTPS وتخزين آمن. لا توجد مزامنة أو جلسات على أجهزة أخرى في هذه النسخة.</p><button class="button" data-action="switch-user">${icon('users')}تبديل الفرد التجريبي</button></section>`;}

function favoriteKeys(){const pinned=state.favorites[state.currentUser]||[],counts={};state.expenses.filter(e=>e.user===state.currentUser).forEach(e=>{const k=e.category+'|'+e.sub;counts[k]=(counts[k]||0)+1;});return [...new Set([...pinned,...Object.keys(counts).sort((a,b)=>counts[b]-counts[a])])].filter(k=>state.categories.some(c=>c.id===k.split('|')[0])).slice(0,5);}
function expenseModal(id=null,preset={}){
 const existing=id?state.expenses.find(e=>e.id===id):null;if(existing&&!isAdmin()&&existing.user!==state.currentUser)return;
 const e=existing||{amount:'',date:localDate(),user:state.currentUser,category:(state.categories.find(c=>c.icon==='food')||state.categories[0]).id,sub:'سوبرماركت',merchant:'',payment:'Visa',type:'need',note:'',receipt:null,...preset};
 if(!state.categories.some(c=>c.id===e.category)){e.category=(state.categories.find(c=>c.icon==='food')||state.categories[0]).id;}
 showModal(existing?'تفاصيل المصروف':'خلّينا نسجّل مصروف جديد',`<div class="favorites">${favoriteKeys().map(k=>`<button class="favorite-chip" data-favorite="${escapeHTML(k)}">${icon('star')}${escapeHTML(k.split('|')[1])}</button>`).join('')}</div><form id="expenseForm"><div class="form-grid"><label class="field">المبلغ (JOD)<input name="amount" type="number" min="0.001" max="9999999" step="0.001" required placeholder="0.000" value="${e.amount}" inputmode="decimal"></label><label class="field">التاريخ<input name="date" type="date" required value="${escapeHTML(e.date)}"></label><label class="field">الفرد<select name="user">${(isAdmin()?state.users:[current()]).map(u=>option(u.id,u.name,e.user)).join('')}</select></label><label class="field">المتجر / وصف المصروف<input name="merchant" maxlength="100" placeholder="مثلًا: Carrefour" value="${escapeHTML(e.merchant)}"></label><label class="field">التصنيف<select name="category" id="expenseCategory">${state.categories.map(c=>option(c.id,c.name,e.category)).join('')}</select></label><label class="field">التصنيف الفرعي<input name="sub" id="expenseSub" list="subOptions" required maxlength="80" value="${escapeHTML(e.sub)}"><datalist id="subOptions">${catBy(e.category).subs.map(s=>option(s,s)).join('')}</datalist></label><label class="field">طريقة الدفع<select name="payment">${['Visa','نقدي','تحويل بنكي','محفظة إلكترونية'].map(p=>option(p,p,e.payment)).join('')}</select></label><label class="field">نوع المصروف<select name="type">${option('need','ضروري — Needs',e.type)}${option('want','كمالي — Wants',e.type)}</select></label><label class="field full">ملاحظات<textarea name="note" maxlength="1000" placeholder="التفاصيل التي تحب تتذكرها لاحقًا...">${escapeHTML(e.note)}</textarea></label><label class="field full">صورة الفاتورة <span class="eyebrow">PNG أو JPG أو WebP · حتى 10 MB</span><input name="receipt" type="file" accept="image/png,image/jpeg,image/webp"></label>${e.receipt?`<label class="inline-check"><input type="checkbox" name="removeReceipt">إزالة الفاتورة الحالية</label>`:''}<label class="inline-check"><input name="favorite" type="checkbox" ${(state.favorites[state.currentUser]||[]).includes(e.category+'|'+e.sub)?'checked':''}>تثبيت ضمن المفضلة</label></div><p class="form-error" id="expenseError" role="alert"></p><div class="form-actions">${existing?`<button type="button" class="button danger" id="deleteExpense">حذف المصروف</button>`:''}<button type="button" class="button" data-action="close-modal">إلغاء</button><button class="button primary" type="submit">${icon('check')}حفظ المصروف</button></div></form>`);
 const form=$('#expenseForm');
 $('#expenseCategory').addEventListener('change',()=>setExpenseCategory($('#expenseCategory').value));
 $$('[data-favorite]').forEach(b=>b.addEventListener('click',()=>{const [category,sub]=b.dataset.favorite.split('|');setExpenseCategory(category,sub);form.elements.favorite.checked=(state.favorites[state.currentUser]||[]).includes(b.dataset.favorite);}));
 if(existing)$('#deleteExpense').addEventListener('click',()=>{showModal('حذف المصروف؟',`<p>سيتم حذف ${escapeHTML(e.merchant||e.sub)} بمبلغ ${money(e.amount)} دينار.</p><div class="form-actions"><button class="button" id="cancelDelete">رجوع</button><button class="button danger" id="confirmDelete">حذف المصروف</button></div>`);$('#cancelDelete').onclick=()=>expenseModal(id);$('#confirmDelete').onclick=()=>{if(state.cloud)return cloudMutate(()=>cloud.deleteExpense(state.householdId,existing),'تم حذف المصروف');if(commit(()=>state.expenses=state.expenses.filter(x=>x.id!==id))){closeModal();render();toast('تم حذف المصروف');}};});
 form.addEventListener('submit',async event=>{event.preventDefault();const f=new FormData(form),amount=Number(f.get('amount'));if(!Number.isFinite(amount)||amount<=0)return;const submit=form.querySelector('[type="submit"]');submit.disabled=true;try{let receipt=e.receipt;const file=f.get('receipt');if(f.get('removeReceipt'))receipt=null;if(file?.size){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('اختر صورة PNG أو JPG أو WebP بحجم لا يتجاوز 10 MB.');receipt=await readFile(file,'data');}const item={id:id||uid(),amount:Math.round(amount*1000)/1000,date:f.get('date'),user:isAdmin()?f.get('user'):state.currentUser,category:f.get('category'),sub:f.get('sub').trim(),merchant:f.get('merchant').trim(),payment:f.get('payment'),type:f.get('type'),note:f.get('note').trim(),receipt};if(!item.sub)throw Error('أدخل التصنيف الفرعي.');if(state.cloud){await cloudMutate(async()=>{const result=await cloud.saveExpense(state.householdId,item,existing,{file,removeReceipt:!!f.get('removeReceipt'),favorite:!!f.get('favorite')});month=item.date.slice(0,7);return result;},existing?'تم تحديث المصروف':'تم حفظ المصروف','#expenseError');return;}const ok=commit(()=>{if(existing)state.expenses[state.expenses.findIndex(x=>x.id===id)]=item;else state.expenses.push(item);const key=item.category+'|'+item.sub;let fav=state.favorites[state.currentUser]||[];state.favorites[state.currentUser]=f.get('favorite')?[...new Set([...fav,key])]:fav.filter(k=>k!==key);});if(ok){month=item.date.slice(0,7);closeModal();render();toast(existing?'تم تحديث المصروف':'تم حفظ المصروف، وكل الأرقام تحدّثت');}}catch(err){$('#expenseError').textContent=err.message;}finally{submit.disabled=false;}});
}
function setExpenseCategory(id,sub){$('#expenseCategory').value=id;$('#expenseSub').value=sub||catBy(id).subs[0];$('#subOptions').innerHTML=catBy(id).subs.map(s=>option(s,s)).join('');}
function quickAdd(event){event.preventDefault();const raw=$('#quickInput').value,normalized=raw.replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/٫/g,'.');const match=normalized.match(/\d+(?:\.\d+)?/);if(!match||Number(match[0])<=0){toast('اكتب مبلغًا صحيحًا مع الوصف، مثل: 12 دينار أوبر');return;}let category='other',sub='أخرى';const words=normalized.toLowerCase();for(const c of state.categories){const s=c.subs.find(s=>words.includes(s.toLowerCase()));if(s){category=c.id;sub=s;break;}if(words.includes(c.name)){category=c.id;sub=c.subs[0];}}if(/أوبر|اوبر|uber|taxi|تكسي/.test(words)){category='transport';sub='Uber / Taxi';}if(/carrefour|كرفور|كارفور/.test(words)){category='food';sub='سوبرماركت';}expenseModal(null,{amount:Number(match[0]),category,sub,merchant:normalized.replace(match[0],'').replace(/دينار|jod/gi,'').trim(),type:['مطاعم','قهوة','حلويات'].includes(sub)||['entertainment','shopping','gifts'].includes(category)?'want':'need'});}
function readFile(file,mode){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('تعذرت قراءة الملف'));mode==='data'?r.readAsDataURL(file):r.readAsText(file);});}
function editBudget(kind,id){if(!isAdmin())return;if(state.cloud)return kind==='household'?editMonthlyBudget():cloudBudgetModal(kind,id);if(kind==='household'){editMonthlyBudget();return;}let target,name;if(kind==='household'){target=state;name='البيت';}else if(kind==='user'){target=userBy(id);name=target.name;}else{target=catBy(id);name=target.name;}showModal(`ميزانية ${name}`,`<form id="budgetForm"><label class="field">السقف الشهري (JOD)<input name="budget" type="number" min="0" max="99999999" step="0.001" required value="${target.budget}"></label><p class="eyebrow">يُطبَّق هذا السقف على جميع الأشهر.</p><div class="form-actions"><button type="button" class="button" data-action="close-modal">إلغاء</button><button class="button primary">حفظ الميزانية</button></div></form>`);$('#budgetForm').onsubmit=event=>{event.preventDefault();const value=Number(new FormData(event.target).get('budget'));if(value>=0&&commit(()=>target.budget=value)){closeModal();render();toast('تم تحديث الميزانية');}};}
function memberModal(id){if(!isAdmin())return;if(state.cloud)return cloudMemberModal(id);const u=id?userBy(id):null;showModal(u?'تعديل فرد العائلة':'أهلًا بفرد جديد',`<form id="memberForm"><div class="form-grid"><label class="field full">الاسم الكامل<input name="name" required maxlength="60" value="${escapeHTML(u?.name||'')}"></label><label class="field full">البريد الإلكتروني (اختياري)<input type="email" name="email" maxlength="254" value="${escapeHTML(u?.email||'')}"></label><label class="field">الميزانية الشهرية (JOD)<input type="number" name="budget" min="0" max="99999999" step="0.001" required value="${u?.budget??0}"></label><label class="field">الدور<select name="role">${option('member','فرد العائلة',u?.role)}${option('admin','مدير العائلة',u?.role)}</select></label></div><p class="form-error" id="memberError"></p><div class="form-actions">${u&&u.id!==state.currentUser?'<button type="button" class="button danger" id="removeMember">حذف الفرد</button>':''}<button type="button" class="button" data-action="close-modal">إلغاء</button><button class="button primary">حفظ الفرد</button></div></form>`);$('#memberForm').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),name=f.get('name').trim();if(!name)return;if(u?.role==='admin'&&f.get('role')==='member'&&state.users.filter(x=>x.role==='admin').length===1){$('#memberError').textContent='يجب أن يبقى مدير واحد على الأقل للعائلة.';return;}if(commit(()=>{if(u)Object.assign(u,{name,short:name.split(' ')[0],email:f.get('email').trim(),budget:Number(f.get('budget')),role:f.get('role')});else state.users.push({id:uid(),name,short:name.split(' ')[0],email:f.get('email').trim(),budget:Number(f.get('budget')),role:f.get('role'),color:'#e7eee1',ink:'#7d936d'});})){closeModal();render();toast('تم حفظ بيانات الفرد');}};$('#removeMember')?.addEventListener('click',()=>{if(state.expenses.some(e=>e.user===id)||(state.incomes||[]).some(i=>i.user===id)){$('#memberError').textContent='هذا الفرد لديه دخل أو مصاريف مسجلة. انقل عملياته أو احذفها قبل حذف الفرد.';return;}showModal('حذف فرد العائلة',`<p>حذف ${escapeHTML(u.name)} من هذه المساحة؟</p><div class="form-actions"><button class="button" data-action="close-modal">إلغاء</button><button class="button danger" id="confirmRemoveMember">حذف الفرد</button></div>`);$('#confirmRemoveMember').onclick=()=>{if(commit(()=>{state.users=state.users.filter(x=>x.id!==id);delete state.favorites[id];})){closeModal();render();toast('تم حذف الفرد');}};});}
function memberDetails(id){if(!isAdmin()&&id!==state.currentUser)return;const u=userBy(id),list=entries(month,id);showModal(`مصروف ${u.short} · ${monthName(month)}`,`<div class="report-comparison"><div><small>المصروف</small><strong>${money(sum(list))} JOD</strong></div><div><small>الميزانية</small><strong>${money(u.budget)} JOD</strong></div></div><div class="budget-list">${categoryTotals(list).map(c=>budgetRow(c.name,u.budget,c.total,'user',u.id,c.color)).join('')||'<p class="eyebrow">لا توجد مصاريف في هذا الشهر</p>'}</div><div class="form-actions"><button class="button primary" id="viewMemberExpenses">عرض جميع المصاريف</button></div>`);$('#viewMemberExpenses').onclick=()=>{scope='all';filters.user=id;closeModal();if(page==='expenses')render();else location.hash='expenses';};}
function categoryModal(id){if(!isAdmin())return;const c=id?catBy(id):null;showModal(c?'تعديل التصنيف':'تصنيف جديد لمصاريفك',`<form id="categoryForm"><div class="form-grid"><label class="field">اسم التصنيف<input name="name" required maxlength="50" value="${escapeHTML(c?.name||'')}"></label><label class="field">الميزانية الشهرية (JOD)<input name="budget" type="number" min="0" max="99999999" step="0.001" required value="${c?.budget??0}"></label><label class="field full">التصنيفات الفرعية (افصل بفاصلة)<textarea name="subs" required maxlength="700">${escapeHTML(c?.subs.join('، ')||'')}</textarea></label></div><p id="categoryError" class="form-error"></p><div class="form-actions"><button type="button" class="button" data-action="close-modal">إلغاء</button><button class="button primary">حفظ التصنيف</button></div></form>`);$('#categoryForm').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),name=f.get('name').trim(),subs=[...new Set(f.get('subs').split(/[,،\n]/).map(s=>s.trim()).filter(Boolean))];if(!name||!subs.length||state.categories.some(x=>x.id!==id&&x.name===name)){$('#categoryError').textContent='أدخل اسمًا غير مكرر وتصنيفًا فرعيًا واحدًا على الأقل.';return;}if(state.cloud)return cloudMutate(()=>cloud.saveCategory(state.householdId,{...c,name,subs,budget:Number(f.get('budget'))}),'تم حفظ التصنيف','#categoryError');if(commit(()=>{if(c)Object.assign(c,{name,subs,budget:Number(f.get('budget'))});else state.categories.push({id:uid(),name,subs,budget:Number(f.get('budget')),color:'#9aaf83',icon:'layers'});})){closeModal();render();toast('تم حفظ التصنيف');}};}
function switchUser(){if(!state)return;if(state.cloud)return cloudAccountMenu();showModal('اختَر فرد العائلة',`<p class="eyebrow">تبديل تجريبي محلي، وليس تسجيل دخول.</p><div class="member-select-list">${state.users.map(u=>`<button data-switch="${escapeHTML(u.id)}">${avatar(u)}${escapeHTML(u.name)}<small>${u.role==='admin'?'مدير':'عضو'} ${u.id===state.currentUser?'· الحالي':''}</small></button>`).join('')}</div>`);$$('[data-switch]').forEach(b=>b.onclick=()=>{if(commit(()=>state.currentUser=b.dataset.switch)){scope='all';search='';Object.keys(filters).forEach(k=>filters[k]='');closeModal();render();toast(`أهلًا ${current().short}`);}});}
function download(content,filename,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const list=page==='expenses'?filtered():entries();const rows=[['التاريخ','الفرد','التصنيف','التصنيف الفرعي','المتجر','الملاحظات','طريقة الدفع','النوع','المبلغ JOD'],...list.map(e=>[e.date,userBy(e.user).name,catBy(e.category).name,e.sub,e.merchant,e.note,e.payment,e.type==='need'?'ضروري':'كمالي',e.amount])];const csv=rows.map(row=>row.map(v=>{let s=String(v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');download('\uFEFF'+csv,`bayt-expenses-${month}.csv`,'text/csv;charset=utf-8');toast('تم تصدير المصاريف');}
function backup(){if(state.cloud)return cloudBackup();let data=state;if(!isAdmin()){data={...state,currentUser:current().id,users:[{...current(),role:'admin'}],expenses:state.expenses.filter(e=>e.user===state.currentUser),incomes:(state.incomes||[]).filter(i=>i.user===state.currentUser),favorites:{[state.currentUser]:state.favorites[state.currentUser]||[]}};}download(JSON.stringify(data,null,2),`bayt-backup-${localDate()}.json`,'application/json');toast('تم تنزيل النسخة الاحتياطية');}
async function restoreBackup(event){if(CLOUD_ENABLED)return;const file=event.target.files[0];if(!file||!isAdmin())return;try{if(file.size>20*1024*1024)throw Error('حجم النسخة أكبر من 20 MB.');const data=JSON.parse(await readFile(file,'text'));if(!validState(data))throw Error('الملف ليس نسخة احتياطية صالحة من تطبيق بيت.');showModal('استعادة نسخة احتياطية',`<p>تحتوي نسخة ${escapeHTML(data.household)} على ${data.expenses.length} مصروف و${data.users.length} أفراد. ستستبدل بياناتك الحالية بالكامل.</p><div class="form-actions"><button class="button" data-action="close-modal">إلغاء</button><button class="button primary" id="confirmRestore">استبدال البيانات واستعادة النسخة</button></div>`);$('#confirmRestore').onclick=()=>{if(commit(()=>state=data)){scope='all';search='';Object.keys(filters).forEach(k=>filters[k]='');closeModal();render();toast('تمت استعادة النسخة الاحتياطية');}};}catch(err){toast(err.message);}event.target.value='';}
function saveSettings(e){e.preventDefault();if(!isAdmin())return;if(state.cloud){const f=new FormData(e.target);return cloudMutate(()=>cloud.saveHousehold(state.householdId,f.get('household').trim(),!!f.get('share')),'تم حفظ الإعدادات');}const name=new FormData(e.target).get('household').trim();if(name&&commit(()=>state.household=name)){render();toast('تم حفظ اسم العائلة');}}
async function shareReport(){const text=`تقرير ${state.household} — ${monthName(month)}\nإجمالي المصاريف: ${money(sum(entries()))} JOD\nالدخل الإضافي: ${money(sum(incomeEntries()))} JOD\nعدد المصاريف: ${entries().length}\n${categoryTotals().slice(0,5).map(c=>`${c.name}: ${money(c.total)} JOD`).join('\n')}`;try{if(navigator.share){await navigator.share({title:'تقرير مصاريف بيت',text});}else if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);toast('تم نسخ ملخص التقرير للمشاركة');}else{download(text,`bayt-report-${month}.txt`,'text/plain;charset=utf-8');toast('تم تنزيل ملخص التقرير للمشاركة');}}catch(err){if(err.name!=='AbortError')toast('تعذرت المشاركة. يمكنك تصدير التقرير أو طباعته.');}}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||(!state&&b.dataset.action!=='close-modal'))return;const action=b.dataset.action,id=b.dataset.id;if(action==='add-expense')expenseModal();else if(action==='edit-expense')expenseModal(id);else if(action==='close-modal')closeModal();else if(action==='scope'){scope=b.dataset.scope;render();}else if(action==='go-budgets')location.hash='budgets';else if(action==='csv')exportCSV();else if(action==='clear-filters'){search='';Object.keys(filters).forEach(k=>filters[k]='');render();}else if(action==='edit-budget')editBudget(b.dataset.kind,id);else if(action==='add-member')memberModal();else if(action==='edit-member')memberModal(id);else if(action==='member-details')memberDetails(id);else if(action==='add-category')categoryModal();else if(action==='edit-category')categoryModal(id);else if(action==='category-expense')expenseModal(null,{category:id,sub:catBy(id).subs[0]});else if(action==='backup')backup();else if(action==='switch-user')switchUser();else if(action==='print')window.print();else if(action==='share-report')shareReport();else if(action==='receipt'){const e=state.expenses.find(x=>x.id===id);if(e?.receipt&&state.cloud){cloudReceipt(e);return;}if(e&&(isAdmin()||e.user===state.currentUser)&&e.receipt)showModal('صورة الفاتورة',`<img class="receipt-preview" src="${escapeHTML(e.receipt)}" alt="فاتورة ${escapeHTML(e.merchant)}">`);}});
$('#closeModal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#profileButton').onclick=switchUser;$('#householdButton').onclick=()=>location.hash='settings';$('#notificationsButton').onclick=()=>{if(!state)return;const list=alerts();showModal('تنبيهات تساعدك تخطّط',list.length?list.map(a=>`<div class="alert-row">${icon('spark')}<div><strong>${escapeHTML(a.title)}</strong>${escapeHTML(a.text)}</div></div>`).join(''):'<div class="empty-state">كل الميزانيات في المسار الصحيح لهذا الشهر.</div>');};
$('#menuButton').onclick=()=>$('#sidebar').classList.toggle('open');
document.addEventListener('click',e=>{if($('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menuButton'))$('#sidebar').classList.remove('open');});
window.addEventListener('hashchange',()=>{$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',e=>{if(CLOUD_ENABLED)return;if(e.key===KEY&&e.newValue){try{const data=JSON.parse(e.newValue);if(validState(data)){state=data;render();toast('تم تحديث البيانات من نافذة أخرى');}}catch{}}});
hydrate();if(!CLOUD_ENABLED){render();try{if(!localStorage.getItem(KEY))save();}catch{}if(storageError)toast('تعذرت قراءة البيانات المحفوظة.');}

